// The link graph, drawn as plain svg: which of your org files point at each
// other, around the one you are looking at.
//
// The layout is the small force simulation in `forcelayout.ts`, driven by
// `useForceLayout`. It used to live in this file; it moved out when the links
// tab grew a second graph - your documents and the places on the internet they
// reach - because two pictures of two different things should still settle the
// same way, and the only way to rely on that is for them to be the same code.
//
// The thing the drawing is really trying to say is which links run both ways. A
// one way link is a thin neutral stroke with a single arrow head; a pair of nodes
// that link at each other is one thicker violet stroke with a head at each end,
// so a bidirectional link reads as a single relationship rather than two
// overlapping arrows.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Typography from '@mui/joy/Typography';
import { LinkGraphResult, LinkGraphNode } from '../db';
import { FNode, FEdge } from '../forcelayout';
import { useForceLayout } from '../useForceLayout';

export type LinkGraphProps = {
    data: LinkGraphResult | null;
    height?: number;
    onPick?: (node: LinkGraphNode) => void;
    selected?: string;
};

// Joy tokens, so the picture follows the colour scheme rather than fighting it.
const C = {
    oneWay: 'var(--joy-palette-neutral-400)',
    both: 'var(--joy-palette-primary-400)',
    broken: 'var(--joy-palette-danger-400)',
    file: 'var(--joy-palette-primary-500)',
    heading: 'var(--joy-palette-success-500)',
    center: 'var(--joy-palette-warning-400)',
    ring: 'var(--joy-palette-background-surface)',
    text: 'var(--joy-palette-text-primary)',
    dim: 'var(--joy-palette-text-tertiary)',
};

function radius(n: LinkGraphNode): number {
    const deg = n.In + n.Out;
    return (n.Center ? 11 : 7) + Math.sqrt(deg) * 2.2;
}

function shortLabel(s: string, max: number = 18): string {
    if (s.length <= max) return s;
    return s.slice(0, max - 1) + '…';
}

export default function LinkGraph({ data, height = 320, onPick, selected }: LinkGraphProps) {
    const [hover, setHover] = React.useState<string | null>(null);

    const nodes = React.useMemo(() => (data && data.Nodes) || [], [data]);
    const edges = React.useMemo(() => (data && data.Edges) || [], [data]);

    // The shapes the layout works in. A node is a radius and a label width; an
    // edge is a pull. Everything else about a node - what it is called, whether
    // it is the one at the centre - is this file's business and not the
    // simulation's.
    const fnodes = React.useMemo<FNode[]>(() => nodes.map(n => ({
        id: n.Id,
        r: radius(n),
        labelHalf: shortLabel(n.Label).length * (n.Center ? 3.4 : 2.9),
        center: n.Center,
    })), [nodes]);
    const fedges = React.useMemo<FEdge[]>(() => edges.map(e => ({
        from: e.From,
        to: e.To,
        weight: 1 + Math.min(2, Math.log2(1 + e.Count + e.Back)) * 0.35,
    })), [edges]);

    const distanceOf = React.useCallback((n: FNode) => {
        const g = nodes.find(x => x.Id === n.id);
        return g ? g.Distance : 1;
    }, [nodes]);

    const layout = useForceLayout(fnodes, fedges, height, distanceOf);
    const { wrapRef, size, pos } = layout;

    // Which nodes sit at each end of an edge, and who is adjacent to whom.
    const adj = React.useMemo(() => {
        const m = new Map<string, Set<string>>();
        for (const e of edges) {
            if (!m.has(e.From)) m.set(e.From, new Set());
            if (!m.has(e.To)) m.set(e.To, new Set());
            m.get(e.From)!.add(e.To);
            m.get(e.To)!.add(e.From);
        }
        return m;
    }, [edges]);

    if (!data) {
        return (
            <Box ref={wrapRef} sx={{ height, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>No graph yet.</Typography>
            </Box>
        );
    }
    if (nodes.length === 0) {
        return (
            <Box ref={wrapRef} sx={{ height, display: 'flex', alignItems: 'center', justifyContent: 'center', px: 2, textAlign: 'center' }}>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    {data.Msg !== '' ? data.Msg : 'Nothing links to or from this file yet.'}
                </Typography>
            </Box>
        );
    }

    // Only one node at a time is lit, and only while it is pointed at or a
    // caller has picked one out: with nothing lit the whole graph draws at full
    // strength rather than dimming itself down to one neighbourhood.
    const lit = hover !== null ? hover : (selected || null);
    const near = lit !== null ? adj.get(lit) : undefined;
    const isLit = (id: string) => lit === null || lit === id || (near !== undefined && near.has(id));

    return (
        <Box ref={wrapRef} sx={{ width: '100%', height, position: 'relative' }}>
            <svg
                width={size.w}
                height={size.h}
                viewBox={`0 0 ${size.w} ${size.h}`}
                style={{ display: 'block', touchAction: 'none', cursor: layout.dragging ? 'grabbing' : 'default' }}
                {...layout.svgHandlers}
            >
                <defs>
                    <radialGradient id="lg-glow">
                        <stop offset="0%" stopColor={C.center} stopOpacity="0.42" />
                        <stop offset="100%" stopColor={C.center} stopOpacity="0" />
                    </radialGradient>
                    <radialGradient id="lg-wash" cx="50%" cy="45%">
                        <stop offset="0%" stopColor={C.both} stopOpacity="0.10" />
                        <stop offset="100%" stopColor={C.both} stopOpacity="0" />
                    </radialGradient>
                    {[
                        { id: 'lg-head-one', fill: C.oneWay },
                        { id: 'lg-head-both', fill: C.both },
                        { id: 'lg-head-broken', fill: C.broken },
                    ].map(m => (
                        <marker
                            key={m.id}
                            id={m.id}
                            viewBox="0 0 10 10"
                            refX="9"
                            refY="5"
                            markerWidth="6"
                            markerHeight="6"
                            orient="auto-start-reverse"
                        >
                            <path d="M 0 1 L 10 5 L 0 9 z" fill={m.fill} />
                        </marker>
                    ))}
                </defs>

                <rect x="0" y="0" width={size.w} height={size.h} fill="url(#lg-wash)" />

                {/* Edges first, so the nodes sit on top of them. */}
                <g>
                    {edges.map(e => {
                        const pa = pos.get(e.From);
                        const pb = pos.get(e.To);
                        if (!pa || !pb) return null;
                        const on = isLit(e.From) && isLit(e.To);
                        const stroke = e.Broken ? C.broken : e.Both ? C.both : C.oneWay;
                        const head = e.Broken ? 'lg-head-broken' : e.Both ? 'lg-head-both' : 'lg-head-one';
                        const width = (e.Both ? 2.1 : 1.2) + Math.min(2.6, Math.log2(1 + e.Count + e.Back) * 0.7);
                        // A gentle bow, so two nodes are joined by a curve rather
                        // than a ruled line and crossings stay readable.
                        const mx = (pa.x + pb.x) / 2;
                        const my = (pa.y + pb.y) / 2;
                        const dx = pb.x - pa.x;
                        const dy = pb.y - pa.y;
                        const len = Math.max(1, Math.hypot(dx, dy));
                        const bow = Math.min(26, len * 0.14);
                        const qx = mx - (dy / len) * bow;
                        const qy = my + (dx / len) * bow;
                        const label = e.Both
                            ? `${e.Count + e.Back} links, both ways`
                            : `${e.Count + e.Back} link${e.Count + e.Back === 1 ? '' : 's'}`;
                        return (
                            <path
                                key={`${e.From}|${e.To}`}
                                d={`M ${pa.x.toFixed(1)} ${pa.y.toFixed(1)} Q ${qx.toFixed(1)} ${qy.toFixed(1)} ${pb.x.toFixed(1)} ${pb.y.toFixed(1)}`}
                                fill="none"
                                stroke={stroke}
                                strokeWidth={width}
                                strokeLinecap="round"
                                strokeDasharray={e.Broken ? '5 4' : undefined}
                                opacity={on ? (e.Both ? 0.95 : 0.7) : 0.12}
                                markerEnd={e.Count > 0 ? `url(#${head})` : undefined}
                                markerStart={e.Back > 0 ? `url(#${head})` : undefined}
                            >
                                <title>{label}</title>
                            </path>
                        );
                    })}
                </g>

                {/* Nodes */}
                <g>
                    {nodes.map(n => {
                        const p = pos.get(n.Id);
                        if (!p) return null;
                        const r = radius(n);
                        const on = isLit(n.Id);
                        const fill = n.Center ? C.center : n.Kind === 'heading' ? C.heading : C.file;
                        return (
                            <g
                                key={n.Id}
                                transform={`translate(${p.x.toFixed(1)} ${p.y.toFixed(1)})`}
                                opacity={on ? 1 : 0.22}
                                style={{ cursor: 'pointer' }}
                                onPointerDown={e => layout.onNodePointerDown(e, n.Id)}
                                onMouseEnter={() => setHover(n.Id)}
                                onMouseLeave={() => setHover(null)}
                                onClick={() => {
                                    // A drag that moved is not a click: letting
                                    // go of a node you have just dragged across
                                    // the canvas must not open it.
                                    if (!layout.wasDrag() && onPick) onPick(n);
                                }}
                            >
                                {n.Center && <circle r={r * 2.6} fill="url(#lg-glow)" />}
                                <circle r={r} fill={fill} stroke={C.ring} strokeWidth={2} />
                                {n.Kind === 'heading' && <circle r={Math.max(2, r * 0.32)} fill={C.ring} opacity={0.75} />}
                                <text
                                    y={r + 12}
                                    textAnchor="middle"
                                    fontSize={n.Center ? 12 : 10.5}
                                    fontWeight={n.Center ? 700 : 500}
                                    fill={C.text}
                                    stroke={C.ring}
                                    strokeWidth={3}
                                    paintOrder="stroke"
                                    style={{ pointerEvents: 'none', userSelect: 'none' }}
                                >
                                    {shortLabel(n.Label)}
                                </text>
                                <title>
                                    {`${n.Label}\n${n.Filename}\n${n.In} in, ${n.Out} out`}
                                </title>
                            </g>
                        );
                    })}
                </g>
            </svg>

            {/* Legend */}
            <Box
                sx={{
                    position: 'absolute',
                    left: 6,
                    bottom: 4,
                    display: 'flex',
                    gap: 1.25,
                    alignItems: 'center',
                    pointerEvents: 'none',
                    flexWrap: 'wrap',
                }}
            >
                {[
                    { c: C.both, t: 'both ways' },
                    { c: C.oneWay, t: 'one way' },
                    { c: C.broken, t: 'broken' },
                ].map(l => (
                    <Box key={l.t} sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                        <Box sx={{ width: 14, height: 0, borderTop: '2px solid', borderColor: l.c }} />
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', fontSize: 10 }}>{l.t}</Typography>
                    </Box>
                ))}
            </Box>
        </Box>
    );
}
