// Org's structure editing, as functions of the file's lines and the cursor.
//
// Each command reads `lines` (the file, split on \n) and a cursor, and returns
// what to change - or null when it does not apply where the cursor is, so the
// key can fall through to whatever it does otherwise. The Files tab's editor
// (components/OrgTextEditor.tsx) turns the answer into one CodeMirror
// transaction, so every command is one undo.
//
// A change is a list of line replacements in the *original* numbering, which
// must not overlap, plus where the cursor and any fields to step through end
// up in the *new* numbering. Lines are 0 based.
//
// Like the highlighter this is not a parser: headings are lines of stars
// outside a block, list items are bullets, and an item owns the lines under
// it that are indented further. That is what org's own commands go by too.

export type Pos = { line: number; ch: number };
export type LineEdit = { from: number; to: number; lines: string[] };
export type FieldAt = { line: number; from: number; to: number; key: string; prompt: string };
// `insert` asks for vim's insert mode (the cursor is somewhere to type), and
// `tidy` that a line whose fields are left empty is taken out again when the
// fields are finished - a property nobody named.
export type Change = { edits: LineEdit[]; cursor?: Pos; fields?: FieldAt[]; insert?: boolean; tidy?: boolean };

// ---------------------------------------------------------------------------
// Reading the outline
// ---------------------------------------------------------------------------

const HEAD = /^(\*+)(\s+)(.*)$/;
const BEGIN = /^\s*#\+begin_/i;
const END = /^\s*#\+end_/i;
const PLAN = /^\s*(SCHEDULED|DEADLINE|CLOSED):/;
const DRAWER_START = /^\s*:PROPERTIES:\s*$/i;
const DRAWER_END = /^\s*:END:\s*$/i;
// A list item: indentation, bullet, space, optional checkbox, the rest. A star
// bullet needs indentation or it is a heading.
const ITEM = /^(\s*)([-+]|\s\*|\d+[.)])(\s+)(\[[ xX-]\]\s+)?(.*)$/;
const COOKIE = /\[(\d*%|\d*\/\d*)\]/;

// Whether each line is inside a #+BEGIN ... #+END block, where nothing is org.
export function blockMask(lines: string[]): boolean[] {
    const out: boolean[] = [];
    let inside = false;
    for (const l of lines) {
        if (!inside && BEGIN.test(l)) { out.push(false); inside = true; continue; }
        if (inside && END.test(l)) { out.push(false); inside = false; continue; }
        out.push(inside);
    }
    return out;
}

export function headingLevel(line: string): number {
    const m = HEAD.exec(line);
    return m ? m[1].length : 0;
}

function isHeading(lines: string[], mask: boolean[], i: number): boolean {
    return i >= 0 && i < lines.length && !mask[i] && headingLevel(lines[i]) > 0;
}

// The heading whose section the line is in, or -1 above the first.
export function sectionOf(lines: string[], line: number, mask = blockMask(lines)): number {
    for (let i = Math.min(line, lines.length - 1); i >= 0; i--) if (isHeading(lines, mask, i)) return i;
    return -1;
}

// One past the last line of a heading's subtree.
export function subtreeEnd(lines: string[], h: number, mask = blockMask(lines)): number {
    const lvl = headingLevel(lines[h]);
    for (let i = h + 1; i < lines.length; i++) {
        if (isHeading(lines, mask, i) && headingLevel(lines[i]) <= lvl) return i;
    }
    return lines.length;
}

// One past the last line of the heading's own text, before its first child.
function sectionEnd(lines: string[], h: number, mask: boolean[]): number {
    for (let i = h + 1; i < lines.length; i++) if (isHeading(lines, mask, i)) return i;
    return lines.length;
}

// The same, less any blank lines it ends with: where something added at the end
// of a section goes, so the blank lines stay between it and what follows.
function contentEnd(lines: string[], from: number, end: number): number {
    while (end > from + 1 && lines[end - 1].trim() === '') end--;
    return end;
}

const indentOf = (s: string) => (/^\s*/.exec(s) as RegExpExecArray)[0].length;

export type Item = { line: number; indent: number; bullet: string; box: string; end: number };

function itemAtLine(lines: string[], i: number, mask: boolean[]): Item | null {
    if (mask[i]) return null;
    const m = ITEM.exec(lines[i]);
    if (!m) return null;
    const indent = m[1].length + (m[2].startsWith(' ') ? 1 : 0);
    let end = i + 1;
    while (end < lines.length && lines[end].trim() !== '' && indentOf(lines[end]) > indent && !isHeading(lines, mask, end)) end++;
    return { line: i, indent, bullet: m[2].trim(), box: (m[4] || '').trim(), end };
}

// The item the cursor is in: on its line, or on a line under it indented
// further. A blank line or a heading ends the search.
export function itemAt(lines: string[], line: number, mask = blockMask(lines)): Item | null {
    for (let i = line; i >= 0; i--) {
        if (lines[i].trim() === '' || isHeading(lines, mask, i)) return null;
        const it = itemAtLine(lines, i, mask);
        if (it) return it.end > line ? it : null;
        if (indentOf(lines[i]) === 0) return null;
    }
    return null;
}

// The items of the list an item is in at its own depth, in order.
function siblings(lines: string[], it: Item, mask: boolean[]): Item[] {
    let top = it.line;
    for (let i = it.line - 1; i >= 0; i--) {
        if (lines[i].trim() === '' || isHeading(lines, mask, i)) break;
        const ind = indentOf(lines[i]);
        if (ind < it.indent) break;
        if (ind === it.indent) { if (itemAtLine(lines, i, mask)) top = i; else break; }
    }
    const out: Item[] = [];
    let i = top;
    while (i < lines.length) {
        const s = itemAtLine(lines, i, mask);
        if (!s || s.indent !== it.indent) break;
        out.push(s);
        i = s.end;
    }
    return out;
}

// The items directly under one, or directly in a section when `it` is null.
function children(lines: string[], from: number, to: number, mask: boolean[]): Item[] {
    const out: Item[] = [];
    let depth = Infinity;
    for (let i = from; i < to; i++) {
        const s = itemAtLine(lines, i, mask);
        if (s && s.indent < depth) depth = s.indent;
    }
    for (let i = from; i < to; i++) {
        const s = itemAtLine(lines, i, mask);
        if (s && s.indent === depth) { out.push(s); i = s.end - 1; }
    }
    return out;
}

function diff(before: string[], after: string[]): LineEdit[] {
    const out: LineEdit[] = [];
    for (let i = 0; i < before.length; i++) {
        if (before[i] !== after[i]) out.push({ from: i, to: i + 1, lines: [after[i]] });
    }
    return out;
}

// ---------------------------------------------------------------------------
// Moving things
// ---------------------------------------------------------------------------

// Swap the heading (and its subtree) or the list item the cursor is in with the
// one before or after it at the same depth.
export function moveThing(lines: string[], cur: Pos, dir: -1 | 1): Change | null {
    const mask = blockMask(lines);
    const it = itemAt(lines, cur.line, mask);
    if (it) {
        const sib = siblings(lines, it, mask);
        const k = sib.findIndex(s => s.line === it.line);
        const other = sib[k + dir];
        if (!other) return null;
        const [a, b] = dir < 0 ? [other, it] : [it, other];
        const swapped = [...lines.slice(b.line, b.end), ...lines.slice(a.line, a.end)];
        const at = dir < 0 ? a.line : a.line + (b.end - b.line);
        return { edits: [{ from: a.line, to: b.end, lines: swapped }], cursor: { line: at + (cur.line - it.line), ch: cur.ch } };
    }
    const h = sectionOf(lines, cur.line, mask);
    if (h < 0) return null;
    const lvl = headingLevel(lines[h]);
    const end = subtreeEnd(lines, h, mask);
    if (dir < 0) {
        let p = -1;
        for (let i = h - 1; i >= 0; i--) if (isHeading(lines, mask, i)) {
            if (headingLevel(lines[i]) < lvl) break;
            if (headingLevel(lines[i]) === lvl) { p = i; break; }
        }
        if (p < 0) return null;
        const swapped = [...lines.slice(h, end), ...lines.slice(p, h)];
        return { edits: [{ from: p, to: end, lines: swapped }], cursor: { line: p + (cur.line - h), ch: cur.ch } };
    }
    if (!isHeading(lines, mask, end) || headingLevel(lines[end]) !== lvl) return null;
    const nend = subtreeEnd(lines, end, mask);
    const swapped = [...lines.slice(end, nend), ...lines.slice(h, end)];
    return { edits: [{ from: h, to: nend, lines: swapped }], cursor: { line: h + (nend - end) + (cur.line - h), ch: cur.ch } };
}

// Promote (-1) or demote (+1) the heading, or dedent / indent the list item.
// `subtree` takes the headings under it along; an item always takes its own
// lines, because an item's children moving away from it changes what they
// belong to.
export function shiftThing(lines: string[], cur: Pos, dir: -1 | 1, subtree: boolean): Change | null {
    const mask = blockMask(lines);
    const it = itemAt(lines, cur.line, mask);
    if (it) {
        if (dir < 0 && it.indent < 2) return null;
        const out = lines.slice(it.line, it.end).map(l => {
            if (l.trim() === '') return l;
            return dir > 0 ? '  ' + l : l.replace(/^ {1,2}/, '');
        });
        return { edits: [{ from: it.line, to: it.end, lines: out }], cursor: { line: cur.line, ch: Math.max(0, cur.ch + 2 * dir) } };
    }
    const h = sectionOf(lines, cur.line, mask);
    if (h < 0) return null;
    const lvl = headingLevel(lines[h]);
    if (dir < 0 && lvl === 1) return null;
    const end = subtree ? subtreeEnd(lines, h, mask) : h + 1;
    if (dir < 0 && subtree) {
        for (let i = h; i < end; i++) if (isHeading(lines, mask, i) && headingLevel(lines[i]) === 1) return null;
    }
    const edits: LineEdit[] = [];
    for (let i = h; i < end; i++) {
        if (!isHeading(lines, mask, i)) continue;
        edits.push({ from: i, to: i + 1, lines: [dir > 0 ? '*' + lines[i] : lines[i].slice(1)] });
    }
    const ch = cur.line === h ? Math.max(0, cur.ch + dir) : cur.ch;
    return { edits, cursor: { line: cur.line, ch } };
}

// ---------------------------------------------------------------------------
// The next thing
// ---------------------------------------------------------------------------

// A new item after the one the cursor is in, or a new heading after the
// section's subtree: "the next one of whatever this is". `todo` makes the
// heading a TODO (or the item a checkbox), as org's M-S-RET does.
// `heading` skips the list item, for org's C-RET: a heading whatever is here.
export function insertNext(lines: string[], cur: Pos, opts: { todo?: string; checkbox?: boolean; heading?: boolean } = {}): Change {
    const mask = blockMask(lines);
    const it = opts.heading ? null : itemAt(lines, cur.line, mask);
    if (it) {
        const m = ITEM.exec(lines[it.line]) as RegExpExecArray;
        const pad = ' '.repeat(it.indent);
        const num = /^(\d+)([.)])$/.exec(it.bullet);
        const bullet = num ? `${Number(num[1]) + 1}${num[2]}` : it.bullet;
        const box = it.box !== '' || opts.checkbox ? '[ ] ' : '';
        const text = `${pad}${bullet}${m[3]}${box}`;
        // The items after it are renumbered, so a numbered list stays one -
        // as part of the same edit, which starts where the new item goes.
        let to = it.end;
        const after: string[] = [];
        if (num) {
            let n = Number(num[1]) + 2;
            for (const s of siblings(lines, it, mask)) {
                if (s.line <= it.line) continue;
                after.push(lines[s.line].replace(/^(\s*)(\d+)([.)])/, (_a, sp, _d, p) => `${sp}${n}${p}`));
                after.push(...lines.slice(s.line + 1, s.end));
                to = s.end;
                n++;
            }
        }
        const edits: LineEdit[] = [{ from: it.end, to, lines: [text, ...after] }];
        return { edits, cursor: { line: it.end, ch: text.length }, insert: true };
    }
    const h = sectionOf(lines, cur.line, mask);
    const lvl = h < 0 ? 1 : headingLevel(lines[h]);
    const at = h < 0 ? cur.line + 1 : contentEnd(lines, h, subtreeEnd(lines, h, mask));
    const text = `${'*'.repeat(lvl)} ${opts.todo ? opts.todo + ' ' : ''}`;
    return { edits: [{ from: at, to: at, lines: [text] }], cursor: { line: at, ch: text.length }, insert: true };
}

// ---------------------------------------------------------------------------
// Checkboxes and statistics
// ---------------------------------------------------------------------------

function setBox(line: string, mark: string): string {
    return line.replace(/^(\s*(?:[-+]|\s\*|\d+[.)])\s+)\[[ xX-]\]/, `$1[${mark}]`);
}

function boxOf(line: string): string {
    const m = ITEM.exec(line);
    return m && m[4] ? m[4].trim()[1] : '';
}

function writeCookie(line: string, done: number, total: number): string {
    return line.replace(COOKIE, (_a, inner: string) =>
        inner.endsWith('%')
            ? `[${total === 0 ? 0 : Math.floor((100 * done) / total)}%]`
            : `[${done}/${total}]`);
}

// Bring a section's derived state up to date: a parent item's box from its
// children's ([X] all, [-] some, [ ] none), every [n/m] / [%] cookie on an item
// from its direct children, and the heading's cookie from the section's
// top-level checkboxes - or, when it has none, from its child headings' todo
// keywords. Works in place on `out`.
export function refreshSection(out: string[], h: number, done: Set<string>, active: Set<string>, mask = blockMask(out)) {
    const from = h < 0 ? 0 : h + 1;
    const to = h < 0 ? (() => { for (let i = 0; i < out.length; i++) if (isHeading(out, mask, i)) return i; return out.length; })() : sectionEnd(out, h, mask);
    // Deepest first, so a parent is worked out from children already settled.
    const items: Item[] = [];
    for (let i = from; i < to; i++) { const s = itemAtLine(out, i, mask); if (s) items.push(s); }
    items.sort((a, b) => b.indent - a.indent);
    for (const it of items) {
        const kids = children(out, it.line + 1, it.end, mask).filter(k => k.box !== '');
        if (kids.length === 0) continue;
        const n = kids.filter(k => boxOf(out[k.line]).toLowerCase() === 'x').length;
        if (boxOf(out[it.line]) !== '') out[it.line] = setBox(out[it.line], n === kids.length ? 'X' : n === 0 ? ' ' : '-');
        if (COOKIE.test(out[it.line])) out[it.line] = writeCookie(out[it.line], n, kids.length);
    }
    if (h < 0 || !COOKIE.test(out[h])) return;
    const top = children(out, from, to, mask).filter(k => k.box !== '');
    if (top.length > 0) {
        out[h] = writeCookie(out[h], top.filter(k => boxOf(out[k.line]).toLowerCase() === 'x').length, top.length);
        return;
    }
    // No checkboxes: the child headings that carry a keyword.
    const lvl = headingLevel(out[h]);
    const end = subtreeEnd(out, h, mask);
    let childLvl = Infinity;
    for (let i = h + 1; i < end; i++) if (isHeading(out, mask, i)) childLvl = Math.min(childLvl, headingLevel(out[i]));
    let n = 0, total = 0;
    for (let i = h + 1; i < end; i++) {
        if (!isHeading(out, mask, i) || headingLevel(out[i]) !== childLvl || childLvl <= lvl) continue;
        const kw = (HEAD.exec(out[i]) as RegExpExecArray)[3].split(/\s+/)[0];
        if (done.has(kw)) { n++; total++; } else if (active.has(kw)) total++;
    }
    out[h] = writeCookie(out[h], n, total);
}

// Tick or untick the checkbox the cursor is in, along with any boxes under it,
// and bring the counts up to date.
export function toggleCheckbox(lines: string[], cur: Pos, done: Set<string>, active: Set<string>): Change | null {
    const mask = blockMask(lines);
    const it = itemAt(lines, cur.line, mask);
    if (!it || it.box === '') return null;
    const out = lines.slice();
    const mark = it.box.toLowerCase() === '[x]' ? ' ' : 'X';
    for (let i = it.line; i < it.end; i++) if (boxOf(out[i]) !== '') out[i] = setBox(out[i], mark);
    refreshSection(out, sectionOf(out, it.line, mask), done, active, mask);
    return { edits: diff(lines, out), cursor: cur };
}

// Add a checkbox to the item the cursor is in, or take it off (org's C-u C-c C-c).
export function toggleHasCheckbox(lines: string[], cur: Pos): Change | null {
    const it = itemAt(lines, cur.line);
    if (!it) return null;
    const l = lines[it.line];
    const next = it.box !== ''
        ? l.replace(/^(\s*(?:[-+]|\s\*|\d+[.)])\s+)\[[ xX-]\]\s+/, '$1')
        : l.replace(/^(\s*(?:[-+]|\s\*|\d+[.)])\s+)/, '$1[ ] ');
    const ch = cur.line === it.line ? Math.max(0, cur.ch + next.length - l.length) : cur.ch;
    return { edits: [{ from: it.line, to: it.line + 1, lines: [next] }], cursor: { line: cur.line, ch } };
}

// Recount the statistics of the section the cursor is in (C-c C-c on a cookie).
export function refreshStats(lines: string[], cur: Pos, done: Set<string>, active: Set<string>): Change | null {
    const out = lines.slice();
    const mask = blockMask(lines);
    const h = sectionOf(lines, cur.line, mask);
    refreshSection(out, h, done, active, mask);
    // The parent's cookie may count this heading's keyword.
    if (h >= 0) {
        const p = parentHeading(out, h, mask);
        if (p >= 0) refreshSection(out, p, done, active, mask);
    }
    const edits = diff(lines, out);
    return edits.length > 0 ? { edits, cursor: cur } : null;
}

function parentHeading(lines: string[], h: number, mask: boolean[]): number {
    const lvl = headingLevel(lines[h]);
    for (let i = h - 1; i >= 0; i--) if (isHeading(lines, mask, i) && headingLevel(lines[i]) < lvl) return i;
    return -1;
}

// ---------------------------------------------------------------------------
// Keywords and priorities
// ---------------------------------------------------------------------------

// The keywords to cycle through: the file's first #+TODO line when it has one
// (what org cycles), otherwise the server's defaults.
export function todoSequence(text: string, fallback: string): string[] {
    const m = /^#\+(?:TODO|SEQ_TODO|TYP_TODO):(.*)$/im.exec(text);
    const spec = m ? m[1] : fallback;
    return spec.split(/\s+/).map(w => w.replace(/\([^)]*\)$/, '')).filter(w => w !== '' && w !== '|');
}

// Move the section heading's keyword one along the sequence (and off the end
// to no keyword), then recount the parent's [n/m] if it has one.
export function cycleTodo(lines: string[], cur: Pos, dir: -1 | 1, seq: string[], done: Set<string>, active: Set<string>): Change | null {
    const mask = blockMask(lines);
    const h = sectionOf(lines, cur.line, mask);
    if (h < 0 || seq.length === 0) return null;
    const m = HEAD.exec(lines[h]) as RegExpExecArray;
    const words = /^(\S+)(\s+|$)(.*)$/.exec(m[3]);
    const kw = words && seq.includes(words[1]) ? words[1] : '';
    const rest = kw ? (words as RegExpExecArray)[3] : m[3];
    const ring = ['', ...seq];
    const next = ring[(ring.indexOf(kw) + dir + ring.length) % ring.length];
    const out = lines.slice();
    out[h] = `${m[1]}${m[2]}${next ? next + (rest ? ' ' : '') : ''}${rest}`;
    if (next === '' && rest === '') out[h] = `${m[1]} `;
    const p = parentHeading(out, h, mask);
    if (p >= 0) refreshSection(out, p, done, active, mask);
    const delta = out[h].length - lines[h].length;
    const ch = cur.line === h && cur.ch > m[1].length ? Math.max(m[1].length + 1, cur.ch + delta) : cur.ch;
    return { edits: diff(lines, out), cursor: { line: cur.line, ch } };
}

// [#A] -> [#B] -> [#C] -> none -> [#A], the other way for dir -1.
export function cyclePriority(lines: string[], cur: Pos, dir: -1 | 1): Change | null {
    const mask = blockMask(lines);
    if (!isHeading(lines, mask, cur.line)) return null;
    const l = lines[cur.line];
    const m = /^(\*+\s+(?:[A-Z][A-Z0-9_-]*\s+)?)(\[#([A-Z])\]\s*)?(.*)$/.exec(l) as RegExpExecArray;
    const ring = ['A', 'B', 'C', ''];
    const now = m[3] || '';
    // Up raises the priority, which is towards A.
    const next = ring[(ring.indexOf(now) - dir + ring.length) % ring.length];
    const out = `${m[1]}${next ? `[#${next}] ` : ''}${m[4]}`;
    return { edits: [{ from: cur.line, to: cur.line + 1, lines: [out] }], cursor: { line: cur.line, ch: Math.min(out.length, cur.ch + out.length - l.length) } };
}

// ---------------------------------------------------------------------------
// Dates
// ---------------------------------------------------------------------------

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const pad = (n: number) => String(n).padStart(2, '0');

export function stampText(d: Date, withTime = false): string {
    const day = `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${DAYS[d.getDay()]}`;
    return withTime ? `${day} ${pad(d.getHours())}:${pad(d.getMinutes())}` : day;
}

const STAMP = /([<[])(\d{4})-(\d{2})-(\d{2})(?: ([A-Za-z]{2,3}\.?))?(?: (\d{1,2}):(\d{2})(?:-(\d{1,2}):(\d{2}))?)?([^\]>\n]*)([>\]])/g;

// The timestamp the cursor is in or touching, as a range of its line.
export function stampAt(line: string, ch: number): { from: number; to: number; m: RegExpExecArray } | null {
    STAMP.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = STAMP.exec(line)) !== null) {
        const from = m.index, to = m.index + m[0].length;
        if (ch >= from && ch <= to) return { from, to, m };
    }
    return null;
}

// Insert a timestamp of today, or select the one the cursor is already on, as
// a field: type over it, or S-up / S-down it into place.
export function timestamp(lines: string[], cur: Pos, active: boolean, now: Date, withTime = false): Change {
    const l = lines[cur.line] || '';
    const s = stampAt(l, cur.ch);
    if (s) {
        return { edits: [], fields: [{ line: cur.line, from: s.from + 1, to: s.to - 1, key: 'date', prompt: 'date' }] };
    }
    const inner = stampText(now, withTime);
    const text = active ? `<${inner}>` : `[${inner}]`;
    const out = l.slice(0, cur.ch) + text + l.slice(cur.ch);
    return {
        edits: [{ from: cur.line, to: cur.line + 1, lines: [out] }],
        fields: [{ line: cur.line, from: cur.ch + 1, to: cur.ch + 1 + inner.length, key: 'date', prompt: 'date' }],
    };
}

// SCHEDULED or DEADLINE on the heading the cursor is under: an existing one is
// selected rather than doubled, a planning line that has the other one gets
// this one beside it, and a heading with neither gets a planning line.
export function plan(lines: string[], cur: Pos, kind: 'SCHEDULED' | 'DEADLINE', now: Date): Change | null {
    const mask = blockMask(lines);
    const h = sectionOf(lines, cur.line, mask);
    if (h < 0) return null;
    const p = h + 1;
    const field = (line: number, text: string, at: number): FieldAt => {
        const s = stampAt(text, at) as { from: number; to: number };
        return { line, from: s.from + 1, to: s.to - 1, key: 'date', prompt: 'date' };
    };
    if (p < lines.length && PLAN.test(lines[p])) {
        const re = new RegExp(`${kind}:\\s*`);
        const has = re.exec(lines[p]);
        if (has) return { edits: [], fields: [field(p, lines[p], has.index + has[0].length + 1)] };
        const out = `${lines[p].replace(/\s+$/, '')} ${kind}: <${stampText(now)}>`;
        return { edits: [{ from: p, to: p + 1, lines: [out] }], fields: [field(p, out, out.length - 2)] };
    }
    // Indented the way the heading's body already is, so it lines up with it.
    const body = p < lines.length && lines[p].trim() !== '' && !isHeading(lines, mask, p) ? (/^\s*/.exec(lines[p]) as RegExpExecArray)[0] : '';
    const out = `${body}${kind}: <${stampText(now)}>`;
    return { edits: [{ from: p, to: p, lines: [out] }], fields: [field(p, out, out.length - 2)] };
}

// Shift the part of the timestamp the cursor is on: year, month, day (the day
// name counts as the day), hour or minute. The day name is put right after.
export function shiftStamp(lines: string[], cur: Pos, delta: number): Change | null {
    const l = lines[cur.line] || '';
    const s = stampAt(l, cur.ch);
    if (!s) return null;
    const m = s.m;
    const rel = cur.ch - s.from;
    const d = new Date(Number(m[2]), Number(m[3]) - 1, Number(m[4]), m[6] ? Number(m[6]) : 0, m[7] ? Number(m[7]) : 0);
    const timeAt = m[6] ? m[0].indexOf(`${m[6]}:${m[7]}`) : -1;
    if (rel <= 4) d.setFullYear(d.getFullYear() + delta);
    else if (rel <= 7) d.setMonth(d.getMonth() + delta);
    else if (timeAt < 0 || rel < timeAt) d.setDate(d.getDate() + delta);
    else if (rel <= timeAt + m[6].length) d.setHours(d.getHours() + delta);
    else d.setMinutes(d.getMinutes() + 5 * delta);
    // A range keeps its length.
    let end = '';
    if (m[8]) {
        const e = new Date(Number(m[2]), Number(m[3]) - 1, Number(m[4]), Number(m[8]), Number(m[9]));
        const was = new Date(Number(m[2]), Number(m[3]) - 1, Number(m[4]), Number(m[6]), Number(m[7]));
        e.setTime(e.getTime() + (d.getTime() - was.getTime()));
        end = `-${pad(e.getHours())}:${pad(e.getMinutes())}`;
    }
    const inner = stampText(d, !!m[6]) + end;
    const text = `${m[1]}${inner}${m[10]}${m[11]}`;
    const out = l.slice(0, s.from) + text + l.slice(s.to);
    return { edits: [{ from: cur.line, to: cur.line + 1, lines: [out] }], cursor: cur };
}

// ---------------------------------------------------------------------------
// Properties
// ---------------------------------------------------------------------------

// A property on the heading the cursor is under: a new line in its drawer, or
// a drawer when it has none, put after the planning line where org keeps it.
// Fields for the name and the value.
export function setProperty(lines: string[], cur: Pos): Change | null {
    const mask = blockMask(lines);
    const h = sectionOf(lines, cur.line, mask);
    if (h < 0) return null;
    let at = h + 1;
    if (at < lines.length && PLAN.test(lines[at])) at++;
    const prop = (line: number, ind: string): FieldAt[] => [
        { line, from: ind.length + 1, to: ind.length + 1, key: 'name', prompt: 'NAME' },
        { line, from: ind.length + 3, to: ind.length + 3, key: 'value', prompt: 'value' },
    ];
    if (at < lines.length && DRAWER_START.test(lines[at])) {
        const ind = (/^\s*/.exec(lines[at]) as RegExpExecArray)[0];
        let end = at + 1;
        while (end < lines.length && !DRAWER_END.test(lines[end]) && !isHeading(lines, mask, end)) end++;
        return { edits: [{ from: end, to: end, lines: [`${ind}:: `] }], fields: prop(end, ind), tidy: true };
    }
    const ind = at < lines.length && lines[at].trim() !== '' && !isHeading(lines, mask, at) ? (/^\s*/.exec(lines[at]) as RegExpExecArray)[0] : '';
    return {
        edits: [{ from: at, to: at, lines: [`${ind}:PROPERTIES:`, `${ind}:: `, `${ind}:END:`] }],
        fields: prop(at + 1, ind),
        tidy: true,
    };
}

// ---------------------------------------------------------------------------
// C-c C-c
// ---------------------------------------------------------------------------

// Org's "do the obvious thing here": tick a checkbox, put a timestamp's day
// name right, or recount the section's statistics.
export function ctrlCCtrlC(lines: string[], cur: Pos, done: Set<string>, active: Set<string>): Change | null {
    const box = toggleCheckbox(lines, cur, done, active);
    if (box) return box;
    if (stampAt(lines[cur.line] || '', cur.ch)) return shiftStamp(lines, cur, 0);
    return refreshStats(lines, cur, done, active);
}
