// Gantt presets: ready-made pieces of a chart's setup that can be switched on
// and off - lanes by assignee, markers from milestone headings, outlines for
// blocked work - so a useful chart is a click away rather than a dialog's
// worth of rules.
//
// A preset only ever touches what it added. Rules it puts in carry its id, so
// switching it off takes back exactly those and leaves the user's own rules
// alone; a lane property or marker query is only cleared when it is still the
// one the preset set, so a preset never undoes something the user changed
// after switching it on.

import { BarRule } from './gantt';

// The part of a chart's setup presets read and write.
export interface PresetState {
    laneProp: string;
    // The marker query as written (not a saved query's name).
    markerQueryText: string;
    barRules: BarRule[];
    critical: boolean;
    health: boolean;
}

export interface GanttPreset {
    id: string;
    label: string;
    hint: string;
    // Part of the one-click Design setup.
    design?: boolean;
    on: (s: PresetState) => boolean;
    add: (s: PresetState) => PresetState;
    remove: (s: PresetState) => PresetState;
}

export const MILESTONE_QUERY = 'HasTags("milestone") || HasTagMatching("^M[0-9]+$")';

// A preset made of bar rules: on when all its rules are there.
function rulesPreset(
    id: string, label: string, hint: string, rules: Omit<BarRule, 'preset'>[], design = false,
): GanttPreset {
    const mine = (s: PresetState) => s.barRules.filter(r => r.preset === id);
    return {
        id, label, hint, design,
        on: s => mine(s).length === rules.length,
        add: s => ({
            ...s,
            barRules: [
                ...s.barRules.filter(r => r.preset !== id),
                ...rules.map(r => ({ ...r, preset: id }) as BarRule),
            ],
        }),
        remove: s => ({ ...s, barRules: s.barRules.filter(r => r.preset !== id) }),
    };
}

export const PRESETS: GanttPreset[] = [
    {
        id: 'lanes-assigned',
        label: 'Lanes by ASSIGNED',
        hint: 'One swim lane per person',
        design: true,
        on: s => s.laneProp === 'ASSIGNED',
        add: s => ({ ...s, laneProp: 'ASSIGNED' }),
        remove: s => (s.laneProp === 'ASSIGNED' ? { ...s, laneProp: '' } : s),
    },
    {
        id: 'milestones',
        label: 'Milestone markers',
        hint: 'Headings tagged :milestone: or :M1:, :M2: … as markers',
        design: true,
        on: s => s.markerQueryText === MILESTONE_QUERY,
        add: s => ({ ...s, markerQueryText: MILESTONE_QUERY }),
        remove: s => (s.markerQueryText === MILESTONE_QUERY ? { ...s, markerQueryText: '' } : s),
    },
    rulesPreset('blocked', 'Outline blocked work', ':blocked: or BLOCKED, outlined in red', [
        { when: 'tag', key: 'blocked', color: '#e74c3c', width: 2.5 },
        { when: 'status', key: 'BLOCKED', color: '#e74c3c', width: 2.5 },
    ], true),
    rulesPreset('pending', 'Hatch unscheduled and submitted', 'No date of its own, or SUBMITTED', [
        { when: 'unscheduled', key: '', fill: 'hatched' },
        { when: 'status', key: 'SUBMITTED', fill: 'hatched' },
    ], true),
    rulesPreset('waiting', 'Dot waiting work', ':waiting: or WAITING, dotted', [
        { when: 'tag', key: 'waiting', fill: 'dotted' },
        { when: 'status', key: 'WAITING', fill: 'dotted' },
    ]),
    rulesPreset('done-hollow', 'Hollow finished work', 'Done tasks drawn as outlines, so open work stands out', [
        { when: 'done', key: '', fill: 'hollow' },
    ]),
    rulesPreset('meetings', 'Meetings as circles', ':meeting: tasks drawn as a circle on their day', [
        { when: 'tag', key: 'meeting', shape: 'circle' },
    ]),
    rulesPreset('external', 'Cross-hatch external work', ':external: or :vendor: - work someone else does', [
        { when: 'tag', key: 'external', fill: 'crosshatch' },
        { when: 'tag', key: 'vendor', fill: 'crosshatch' },
    ]),
    rulesPreset('milestone-tasks', 'Milestone tasks as diamonds', 'Tasks tagged :milestone: drawn as a diamond', [
        { when: 'tag', key: 'milestone', shape: 'diamond' },
    ]),
    {
        id: 'critical',
        label: 'Critical path',
        hint: 'Mark the chain of tasks that decides the end date',
        on: s => s.critical,
        add: s => ({ ...s, critical: true }),
        remove: s => ({ ...s, critical: false }),
    },
    {
        id: 'health',
        label: 'Overdue and slipping',
        hint: 'Flag work past its end, behind its percent, or later than the baseline',
        on: s => s.health,
        add: s => ({ ...s, health: true }),
        remove: s => ({ ...s, health: false }),
    },
];

// The one-click Design setup: every preset marked for it, switched on.
export function applyDesign(s: PresetState): PresetState {
    return PRESETS.filter(p => p.design).reduce((acc, p) => p.add(acc), s);
}
