// Moving headings out of the file you are reading.
//
// The search tab and the kanban board both have rows to act on, so the three
// operations hang off a row there. The file view has a page - rendered html, or
// the file's own text - and no row to hang anything off: the rendered view is a
// shadow root of exported html with no handle on a heading, and the source view
// is lines.
//
// So the file view gets its outline instead. One button, the file's headings
// with a tick beside each, and the three operations under them - which is also
// the one place in the app where "take these four and put them over there" is a
// single gesture rather than four.
//
// The outline comes from `/filecontents/headings`, which answers with every
// heading of one file - its level, its keyword and its hash - so nothing here
// has to parse anything.

import * as React from 'react';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import ModalClose from '@mui/joy/ModalClose';
import Box from '@mui/joy/Box';
import Sheet from '@mui/joy/Sheet';
import Input from '@mui/joy/Input';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import Chip from '@mui/joy/Chip';
import Checkbox from '@mui/joy/Checkbox';
import Alert from '@mui/joy/Alert';
import CircularProgress from '@mui/joy/CircularProgress';
import IconButton from '@mui/joy/IconButton';
import Tooltip from '@mui/joy/Tooltip';
import SearchIcon from '@mui/icons-material/Search';
import DriveFileMoveIcon from '@mui/icons-material/DriveFileMoveOutlined';
import ContentCopyIcon from '@mui/icons-material/ContentCopyOutlined';
import InventoryIcon from '@mui/icons-material/Inventory2Outlined';

import { ODb } from '../db';
import { MoveOp, MoveNode, baseName } from '../move';
import MoveDialog from './MoveDialog';
import { useIsMobile } from '../useMobile';

type Heading = {
    Hash: string;
    Headline: string;
    Status: string;
    Level: number;
    Tags: string[] | null;
};

// The toolbar button and everything behind it.
export default function FileMove({ filename, onDone }: {
    filename: string;
    onDone?: () => void;
}) {
    const isMobile = useIsMobile();
    const [open, setOpen] = React.useState(false);
    const [headings, setHeadings] = React.useState<Heading[]>([]);
    const [loading, setLoading] = React.useState(false);
    const [error, setError] = React.useState('');
    const [query, setQuery] = React.useState('');
    const [ticked, setTicked] = React.useState<string[]>([]);
    const [moveOpen, setMoveOpen] = React.useState(false);
    const [moveOp, setMoveOp] = React.useState<MoveOp>('refile');

    // Read afresh each time. A heading's hash does not survive its file being
    // edited, so an outline kept from the last time this was opened is an
    // outline of hashes that may now belong to other headings - which is the
    // whole reason the batch is one request in the first place.
    React.useEffect(() => {
        if (!open || !filename) return;
        let gone = false;
        setLoading(true); setError(''); setTicked([]); setQuery('');
        ODb.headingsIn(filename)
            .then(r => { if (!gone) setHeadings(r || []); })
            .catch(e => { if (!gone) setError((e && e.message) || 'Could not read the outline.'); })
            .finally(() => { if (!gone) setLoading(false); });
        return () => { gone = true; };
    }, [open, filename]);

    const shown = React.useMemo(() => {
        const q = query.trim().toLowerCase();
        if (q === '') return headings;
        return headings.filter(h =>
            (h.Headline + ' ' + h.Status + ' ' + (h.Tags || []).join(' ')).toLowerCase().includes(q));
    }, [headings, query]);

    const nodes: MoveNode[] = React.useMemo(
        () => headings.filter(h => ticked.includes(h.Hash))
            .map(h => ({ hash: h.Hash, headline: h.Headline, filename })),
        [headings, ticked, filename]);

    const toggle = (hash: string) => setTicked(prev =>
        prev.includes(hash) ? prev.filter(h => h !== hash) : [...prev, hash]);

    const start = (op: MoveOp) => { setMoveOp(op); setMoveOpen(true); };

    return (
        <>
            <Tooltip size="sm" title="Refile, copy or archive headings out of this file">
                <IconButton
                    size="sm" variant="outlined" color="neutral"
                    aria-label="Move headings"
                    disabled={!filename}
                    onClick={() => setOpen(true)}
                >
                    <DriveFileMoveIcon />
                </IconButton>
            </Tooltip>

            <Modal open={open} onClose={() => setOpen(false)}>
                <ModalDialog
                    sx={{
                        width: isMobile ? '96vw' : 560, maxWidth: '96vw', maxHeight: '88vh',
                        display: 'flex', flexDirection: 'column', p: 2,
                    }}
                >
                    <ModalClose />
                    <Typography level="title-md" sx={{ pr: 4 }}>
                        Move headings out of {baseName(filename)}
                    </Typography>
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', mb: 1 }}>
                        Tick what to move. Ticking a heading takes everything under it.
                    </Typography>

                    <Input
                        size="sm"
                        value={query}
                        onChange={e => setQuery(e.target.value)}
                        placeholder="Filter the outline"
                        startDecorator={<SearchIcon />}
                        sx={{ mb: 1 }}
                    />

                    <Sheet
                        variant="outlined"
                        sx={{ flex: 1, minHeight: 160, maxHeight: 360, overflowY: 'auto', borderRadius: 'sm' }}
                    >
                        {loading && <Box sx={{ p: 2 }}><CircularProgress size="sm" /></Box>}
                        {!loading && shown.length === 0 && (
                            <Typography level="body-sm" sx={{ p: 2, color: 'text.tertiary' }}>
                                {headings.length === 0 ? 'This file has no headings.' : 'Nothing matches that.'}
                            </Typography>
                        )}
                        {shown.map(h => (
                            <Box
                                key={h.Hash}
                                onClick={() => toggle(h.Hash)}
                                sx={{
                                    display: 'flex', alignItems: 'center', gap: 1,
                                    // The indent is the outline, which is what makes
                                    // "everything under it" visible rather than a
                                    // rule somebody has to remember.
                                    pl: 1.25 + (h.Level - 1) * 1.5, pr: 1.25,
                                    py: isMobile ? 0.9 : 0.5,
                                    cursor: 'pointer',
                                    borderBottom: '1px solid', borderColor: 'divider',
                                    '&:last-child': { borderBottom: 'none' },
                                    '&:hover': { bgcolor: 'background.level1' },
                                }}
                            >
                                <Checkbox
                                    size="sm"
                                    checked={ticked.includes(h.Hash)}
                                    onChange={() => toggle(h.Hash)}
                                    onClick={e => e.stopPropagation()}
                                />
                                {h.Status && (
                                    <Chip size="sm" variant="soft" color="primary">{h.Status}</Chip>
                                )}
                                <Typography level="body-sm" noWrap sx={{ flex: 1, minWidth: 0 }}>
                                    {h.Headline}
                                </Typography>
                                {(h.Tags || []).length > 0 && (
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                                        :{(h.Tags || []).join(':')}:
                                    </Typography>
                                )}
                            </Box>
                        ))}
                    </Sheet>

                    {error !== '' && <Alert size="sm" color="danger" variant="soft" sx={{ mt: 1 }}>{error}</Alert>}

                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1.5, flexWrap: 'wrap' }}>
                        <Typography level="body-sm" sx={{ color: 'text.tertiary' }}>
                            {ticked.length} ticked
                        </Typography>
                        <Box sx={{ flex: 1 }} />
                        <Button
                            size="sm" variant="outlined" color="neutral"
                            startDecorator={<DriveFileMoveIcon />}
                            disabled={ticked.length === 0}
                            onClick={() => start('refile')}
                        >
                            Refile
                        </Button>
                        <Button
                            size="sm" variant="outlined" color="neutral"
                            startDecorator={<ContentCopyIcon />}
                            disabled={ticked.length === 0}
                            onClick={() => start('copy')}
                        >
                            Copy to
                        </Button>
                        <Button
                            size="sm" variant="outlined" color="warning"
                            startDecorator={<InventoryIcon />}
                            disabled={ticked.length === 0}
                            onClick={() => start('archive')}
                        >
                            Archive
                        </Button>
                    </Box>
                </ModalDialog>
            </Modal>

            <MoveDialog
                open={moveOpen}
                op={moveOp}
                nodes={nodes}
                onClose={() => setMoveOpen(false)}
                onDone={() => {
                    // Both dialogs close and the page is read again: the file
                    // being looked at is the file that just changed.
                    setMoveOpen(false);
                    setOpen(false);
                    onDone?.();
                }}
            />
        </>
    );
}
