import { LayoutMode } from './mobile';
import { StarmapSettings } from './starmap/types';
import { DEF as STARMAP_LOOK } from './starmap/defaults';

// User settings that live in this browser rather than on the server.
//
// They are kept in localStorage under one key, read once at startup and written
// back on every change. Components read them with the useSetting hook, which
// re-renders everyone watching a value when any tab or any part of the app
// changes it - a plain module variable would leave the other readers stale.

export type UserSettings = {
    // The theme the files view renders org files with. Two values are not
    // stylesheet names: "auto" follows the app's own light/dark mode, and
    // "file" leaves the file's own #+HTML_THEME alone.
    htmlTheme: string;

    // The kanban board that was open last. The boards themselves live on the
    // server, because a board names a stored query that lives there too and the
    // pair of them would come apart in another browser; which one you were
    // looking at is about this browser and stays here.
    kanbanBoard: string;

    // The file the column view was last reading. A column view is a thing
    // somebody comes back to about one project, and landing on "pick a file"
    // every time is the tab forgetting what it was for. Which file stays here
    // rather than on the server for the same reason the kanban board does: it is
    // about this browser.
    columnsFile: string;

    // Whether the habit tracker in the agenda is open. It folds to one line
    // saying how today is going, which is the whole of what somebody who is not
    // working on their habits right now wants from it.
    habitsOpen: boolean;

    // How many days of habit history the tracker draws. Eight weeks by default:
    // long enough that a run looks like a run and a gap looks like a gap, short
    // enough to read at a glance rather than study.
    habitDays: number;

    // Which renderer the gantt view draws with: "mermaid" for the diagram
    // mermaid makes of the server's gantt source, or one of "react", "vis" and
    // "google", which are drawn from /gantt/tasks and can be edited. All four
    // are the same schedule - this is a preference about reading it, so it
    // lives in the browser.
    ganttRenderer: GanttRenderer;

    // What a gantt bar's colour means: its state, its keyword, who it is
    // assigned to, its lane, how far along it is, or the value of one property.
    // Kept per browser like the renderer, because it is about reading the plan
    // rather than about the plan.
    ganttColorBy: string;

    // The property `ganttColorBy: 'property'` colours by, e.g. "PRIORITY".
    ganttColorProp: string;

    // The saved gantt view that was open last, by name. The views live on the
    // server (/ext/gantt/views) like kanban boards; which one you were looking
    // at is about this browser. The command palette opens a view by writing it.
    ganttView: string;

    // Which of the gantt toolbar's foldable sections are open, comma
    // separated (query, filter, lanes, markers, appearance). All folded by
    // default: the chart is what the tab is for, the controls are for a while.
    ganttPanels: string;

    // Where the last new marker went, as a JSON Place, so the next one goes
    // there unless told otherwise.
    ganttMarkerPlace: string;

    // The colour scheme the Org source view reads in: a key from ORG_THEMES,
    // or "auto" to follow the app's own light and dark.
    orgTheme: string;

    // Which engine draws the mind map. All three draw the same tree; this is
    // about how you want to read it, so it stays in the browser.
    mindEngine: MindEngine;

    // The collection that was open last in the collections tab. Like the
    // kanban board, which one you were looking at is about this browser.
    collection: string;

    // How the files tab reads a file: the exported page, or its own text.
    //
    // It used to be state inside the tab, which meant it said it kept whatever
    // view you were reading in and then lost it the moment you looked at
    // another tab and came back. A character sheet still overrides it - that
    // is the file's own business - and is never stored, because "sheet" is not
    // a way of reading every file.
    fileView: 'html' | 'source';

    // The keys the Files tab's editor takes: vim (normal, insert and visual
    // modes, shown under the editor) or a small set of emacs ones.
    editorKeys: 'vim' | 'emacs';

    // Whether a search row says which file its heading came out of, in small
    // muted type under the headline. Off by default: most searches are inside
    // one project and the answer is the same on every row, which is a column
    // of noise. On, it is the fastest way to tell two similarly named headings
    // apart.
    searchShowFile: boolean;

    // Whether the search results are gathered under the file each came from.
    // A different question from the one a flat list answers - "what is in each
    // of these files" rather than "what matched" - so it is a mode rather than
    // a sort.
    searchGroupByFile: boolean;

    // Which way the links tab draws: the list, or the web of documents and the
    // places they reach. Two pictures of the same links, so which one you are
    // reading is about this browser and stays here.
    linkView: 'list' | 'graph';

    // What a remote endpoint wears in the graph: letters worked out from its
    // own name, or its favicon.
    //
    // Letters by default, and that is a privacy default rather than a taste
    // one. A favicon is a request to that host - it learns that somebody is
    // looking at a page which mentions it - so it is asked for rather than
    // assumed. See `faviconUrl` in linkweb.ts for why it is never fetched
    // through one of the favicon services.
    linkGraphIcons: 'letter' | 'favicon';

    // Whether the graph draws the links that stay inside the org files, the
    // ones that leave for the internet, or both.
    linkGraphDocs: boolean;
    linkGraphRemotes: boolean;

    // Leave an endpoint out of the graph unless this many links reach it. The
    // long tail of hosts linked exactly once is what stops a real database
    // being readable as a picture.
    linkGraphMinLinks: number;

    // How the links tab gathers its list: not at all, by the service each link
    // points at, or by the file it was written in. About reading rather than
    // about the links, so it stays in the browser.
    linkGroupBy: 'none' | 'service' | 'file';

    // How the code tab gathers its list: not at all, by the language each
    // block is written in, or by the file it lives in. A question about
    // reading rather than about the blocks, so it stays in the browser.
    codeGroupBy: 'none' | 'lang' | 'file';

    // Which layout to draw: "auto" follows the viewport and the pointer,
    // "mobile" and "desktop" force one.
    //
    // The override is here because the automatic answer will be wrong for
    // somebody, and being wrong about this is not a small thing - it decides
    // whether the search results are a table or a list of cards. A phone held
    // in landscape may well want the table; a desktop being used to check what
    // the phone layout looks like certainly wants the cards.
    layout: LayoutMode;

    // Whether the search tab shows records - contacts, equipment, anything
    // with a RECORD property.
    //
    // Off by default, because a contact matches "jane" as readily as the task
    // about ringing her and is rarely the one being looked for. It is a
    // browser setting rather than a server one for the same reason every other
    // one here is: it is about how you read, not about what is written.
    searchRecords: boolean;

    // The starmap's own settings, all of them, as one object.
    //
    // One field rather than twenty-five, because they are twenty-five sliders of
    // one picture and nothing else reads any of them. The engine mutates the
    // object it was handed - a slider writes straight into it so dragging one
    // costs no render - and the panel writes it back here debounced.
    starmap: StarmapPrefs;
};

// What the starmap remembers. `look` is every tunable, and the three above it are
// the decisions about *what* is drawn rather than how it looks.
export type StarmapPrefs = {
    // Whether a star is a heading or a whole file.
    scope: 'heading' | 'file';
    // What a constellation is made of.
    groupBy: 'folder' | 'file';
    // What a star's colour means: which constellation it is in, or what state the
    // heading is in. The second is org's own and the galaxy's ancestor had no
    // equivalent: a sky where everything unfinished is one colour is a different
    // map of the same database.
    colorBy: 'constellation' | 'keyword';
    // An org query restricting which headings are stars.
    query: string;
    // Folders or files to leave out.
    exclude: string;
    // Leave the day pages, journals and session records out.
    noLogs: boolean;
    // How many stars to ask for. The layout is O(n²), so this is the one setting
    // with a performance story behind it.
    limit: number;
    look: StarmapSettings;
};

// Re-exported so that a component reading the `layout` setting does not have to
// import `mobile.ts` as well for the name of its own value.
export type { LayoutMode } from './mobile';

// Four renderers, one schedule. Only mermaid is read-only: it is drawn from
// the exporter's source, which says what a bar is but not which heading.
export type GanttRenderer = 'mermaid' | 'react' | 'vis' | 'google';

// Four engines, one tree. Only mermaid is a picture rather than a map: its
// nodes cannot be moved, which is exactly why it is the one worth exporting.
export type MindEngine = 'elixir' | 'jsmind' | 'markmap' | 'mermaid';

export const HTML_THEME_AUTO = 'auto';
export const HTML_THEME_FILE = 'file';

// Dark by default: the files view is read inside the app, and a white page in a
// dark app is the thing this setting exists to stop happening.
export const defaultSettings: UserSettings = {
    htmlTheme: 'dark',
    kanbanBoard: '',
    columnsFile: '',
    habitsOpen: true,
    habitDays: 56,
    // Mermaid by default: it is the chart this view has always drawn.
    ganttRenderer: 'mermaid',
    ganttColorBy: 'state',
    ganttColorProp: 'PRIORITY',
    ganttView: '',
    ganttPanels: '',
    ganttMarkerPlace: '',
    orgTheme: 'auto',
    // Mind Elixir by default: it is the one that looks like a mind map and the
    // one you can think with.
    mindEngine: 'elixir',
    collection: '',
    fileView: 'html',
    editorKeys: 'vim',
    codeGroupBy: 'none',
    linkGroupBy: 'service',
    linkView: 'list',
    linkGraphIcons: 'letter',
    linkGraphDocs: true,
    linkGraphRemotes: true,
    linkGraphMinLinks: 1,
    searchShowFile: false,
    searchGroupByFile: false,
    searchRecords: false,
    layout: 'auto',
    starmap: {
        // Headings by default: that is where an org database keeps what it is
        // about. At file scope a galaxy of a hundred files is a handful of dots.
        scope: 'heading',
        // Folders by default, because at heading scope the alternative is one
        // constellation per file and a database with four hundred day pages in it
        // would have four hundred constellations of two stars each.
        groupBy: 'folder',
        colorBy: 'constellation',
        query: '',
        exclude: '',
        noLogs: false,
        limit: 4000,
        look: { ...STARMAP_LOOK },
    },
};

const STORAGE_KEY = 'worg.settings';

function load(): UserSettings {
    try {
        const raw = window.localStorage.getItem(STORAGE_KEY);
        if (!raw) return { ...defaultSettings };
        const parsed = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return { ...defaultSettings };
        // Merged onto the defaults so a setting added later still has a value.
        const merged = { ...defaultSettings, ...parsed } as UserSettings;
        // The starmap's settings are an object, so a shallow merge would hand
        // back whatever was stored the last time and silently drop every tunable
        // added since - `look.outline` would arrive undefined and the layout would
        // multiply by NaN. Merged a level deeper for that reason.
        merged.starmap = {
            ...defaultSettings.starmap,
            ...(parsed.starmap || {}),
            look: { ...defaultSettings.starmap.look, ...((parsed.starmap || {}).look || {}) },
        };
        return merged;
    } catch {
        return { ...defaultSettings };
    }
}

let current: UserSettings = load();

type Listener = (s: UserSettings) => void;
const listeners = new Set<Listener>();

export function getSettings(): UserSettings {
    return current;
}

export function setSetting<K extends keyof UserSettings>(key: K, value: UserSettings[K]) {
    if (current[key] === value) return;
    current = { ...current, [key]: value };
    try {
        window.localStorage.setItem(STORAGE_KEY, JSON.stringify(current));
    } catch {
        // A browser with storage turned off still gets the setting for this session.
    }
    listeners.forEach(l => l(current));
}

export function subscribeSettings(l: Listener): () => void {
    listeners.add(l);
    return () => { listeners.delete(l); };
}

// The same settings changed in another tab.
if (typeof window !== 'undefined') {
    window.addEventListener('storage', (ev: StorageEvent) => {
        if (ev.key !== STORAGE_KEY) return;
        current = load();
        listeners.forEach(l => l(current));
    });
}

// Resolve the html theme setting to the name the exporter wants, or '' to let
// the file keep its own theme. mode is the app's current color scheme.
export function resolveHtmlTheme(setting: string, mode: string | undefined): string {
    if (setting === HTML_THEME_FILE) return '';
    if (setting === HTML_THEME_AUTO) return mode === 'light' ? 'default' : 'dark';
    return setting;
}

// What a theme name reads as in a menu or on a button. Anything not listed is
// shown with its first letter capitalised and its underscores opened out, so a
// stylesheet added to the server needs no change here - a name is listed only
// when capitalising it gets it wrong ("Rtd") or when the name alone does not
// say what the page will look like.
//
// It is here rather than beside either of its callers because there are two of
// them - the settings menu, where a theme is being chosen, and the file view's
// own button for the theme a file asked for - and the same theme reading two
// ways in one application is two themes as far as the reader is concerned.
const HTML_THEME_LABELS: Record<string, string> = {
    default: 'Default (light)',
    dark: 'Dark',
    docs: 'Docs',
    rtd: 'Read the Docs',
    furo: 'Furo',
    dnd: 'D&D (parchment)',
};

export function htmlThemeLabel(name: string): string {
    if (HTML_THEME_LABELS[name]) return HTML_THEME_LABELS[name];
    const words = name.replace(/[_-]+/g, ' ').trim();
    if (words === '') return 'Theme';
    return words[0].toUpperCase() + words.slice(1);
}

// The themes that paint a dark page. This matters because a stylesheet that
// never names a background leaves the exported page transparent, and the frame
// it sits in is what shows through - so the ground behind the frame has to be
// the one the page expects.
//
// The themes are discovered from the server's own stylesheet folder rather than
// listed anywhere, so the `_dark` suffix every dark one of them carries counts
// as well as this list: a name added there needs no change here. Add a name to
// the list only for a dark stylesheet that is not called one.
const DARK_HTML_THEMES = new Set(['dark']);

export function isDarkHtmlTheme(theme: string): boolean {
    return DARK_HTML_THEMES.has(theme) || theme.endsWith('_dark');
}
