// Adding and editing a gantt marker: a heading whose date the chart draws as a
// line (one day) or a band (a range of days). The form and its conversions are
// in gantt.ts (MarkerForm, markerFormFrom, markerRequest), pure and tested;
// this is only the dialog around them and the one request that writes.

import * as React from 'react';
import Box from '@mui/joy/Box';
import Typography from '@mui/joy/Typography';
import Button from '@mui/joy/Button';
import Input from '@mui/joy/Input';
import Select from '@mui/joy/Select';
import Option from '@mui/joy/Option';
import Checkbox from '@mui/joy/Checkbox';
import Chip from '@mui/joy/Chip';
import Divider from '@mui/joy/Divider';
import Modal from '@mui/joy/Modal';
import ModalDialog from '@mui/joy/ModalDialog';
import FormControl from '@mui/joy/FormControl';
import FormLabel from '@mui/joy/FormLabel';
import RadioGroup from '@mui/joy/RadioGroup';
import Radio from '@mui/joy/Radio';
import { ODb } from '../db';
import { Place, filePlace, headingPlace, rankPlaces, uniquePlaces } from '../places';
import { headlineQuery } from '../palette';
import {
    GanttMarker, MarkerForm, markerFormFrom, markerFormError, markerRequest, parseGanttDate, dayKey,
} from '../gantt';

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

// The org text the form will write, shown as it is typed so the result is
// never a surprise. Said the way the server writes it (ganttmarker.go).
function previewOf(f: MarkerForm): string {
    const stamp = (date: string, time: string, until: string) => {
        const d = parseGanttDate(date);
        if (!d) return '<…>';
        let s = `${date} ${DAYS[d.getDay()]}`;
        if (f.timed && time) s += ` ${time}${until ? `-${until}` : ''}`;
        return `<${s}>`;
    };
    const a = stamp(f.startDate, f.startTime, f.startUntil);
    if (f.range) return `${a}--${stamp(f.endDate, f.endTime, f.endUntil)}`;
    return f.kind === 'deadline' ? `DEADLINE: ${a}` : a;
}

// Where a new marker goes, found by typing: a box that narrows hundreds of
// files and headings to a handful as it is typed into (the app's fuzzy
// matcher, as the command palette uses), with headings anywhere asked of the
// server once two letters are in. Arrow keys move, Enter picks, and the pick
// shows as one line with a Change button so it is plain where the marker is
// going before it is written.
function PlacePicker({ value, onChange, places }: {
    value: Place | null;
    onChange: (p: Place | null) => void;
    places: Place[];
}) {
    const [text, setText] = React.useState('');
    const [open, setOpen] = React.useState(!value);
    const [cursor, setCursor] = React.useState(0);
    const [headings, setHeadings] = React.useState<Place[]>([]);
    const [looking, setLooking] = React.useState(false);

    React.useEffect(() => {
        const q = text.trim();
        if (!open || q.length < 2) { setHeadings([]); setLooking(false); return; }
        const ctrl = new AbortController();
        setLooking(true);
        const t = window.setTimeout(async () => {
            try {
                const rows = await ODb.query(headlineQuery(q), false, ctrl.signal, '!IsArchived()');
                if (!ctrl.signal.aborted) {
                    setHeadings((Array.isArray(rows) ? rows : []).slice(0, 25)
                        .map((r: any) => headingPlace(r.Hash, r.Headline || '(no headline)', r.Filename || '')));
                }
            } catch {
                if (!ctrl.signal.aborted) setHeadings([]);
            }
            if (!ctrl.signal.aborted) setLooking(false);
        }, 180);
        return () => { window.clearTimeout(t); ctrl.abort(); };
    }, [text, open]);

    const shown = React.useMemo(
        () => rankPlaces(uniquePlaces([...places, ...headings]), text, 40),
        [places, headings, text],
    );
    React.useEffect(() => { setCursor(0); }, [text]);

    if (!open && value) {
        return (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, border: '1px solid', borderColor: 'neutral.outlinedBorder',
                borderRadius: 'sm', px: 1, py: 0.5 }}>
                <Box sx={{ flex: 1, minWidth: 0 }}>
                    <Typography level="body-sm" noWrap>{value.label}</Typography>
                    <Typography level="body-xs" noWrap sx={{ color: 'text.tertiary' }}>{value.hint}</Typography>
                </Box>
                <Button size="sm" variant="plain" onClick={() => { setText(''); setOpen(true); }}>Change</Button>
            </Box>
        );
    }
    const pick = (p: Place) => { onChange(p); setOpen(false); setText(''); };
    return (
        <Box>
            <Input
                size="sm"
                autoFocus={!value}
                value={text}
                placeholder="Type to find a heading or a file…"
                onChange={e => setText(e.target.value)}
                onKeyDown={e => {
                    if (e.key === 'ArrowDown') { e.preventDefault(); setCursor(c => Math.min(c + 1, shown.length - 1)); }
                    else if (e.key === 'ArrowUp') { e.preventDefault(); setCursor(c => Math.max(c - 1, 0)); }
                    else if (e.key === 'Enter') { e.preventDefault(); if (shown[cursor]) pick(shown[cursor]); }
                    else if (e.key === 'Escape' && value) { e.preventDefault(); e.stopPropagation(); setOpen(false); }
                }}
                slotProps={{ input: { 'aria-label': 'Where it goes', role: 'combobox', 'aria-expanded': true } }}
                endDecorator={looking ? <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>…</Typography> : undefined}
            />
            <Box role="listbox" sx={{ mt: 0.5, maxHeight: 220, overflowY: 'auto', border: '1px solid',
                borderColor: 'neutral.outlinedBorder', borderRadius: 'sm' }}>
                {shown.length === 0 && (
                    <Typography level="body-xs" sx={{ color: 'text.tertiary', p: 1 }}>
                        {text.trim().length < 2 ? 'Type to search headings and files' : 'Nothing matches'}
                    </Typography>
                )}
                {shown.map((p, i) => (
                    <Box
                        key={p.value}
                        role="option"
                        aria-selected={i === cursor}
                        ref={(el: HTMLDivElement | null) => { if (el && i === cursor) el.scrollIntoView({ block: 'nearest' }); }}
                        onMouseEnter={() => setCursor(i)}
                        onClick={() => pick(p)}
                        sx={{ px: 1, py: 0.5, cursor: 'pointer', bgcolor: i === cursor ? 'primary.softBg' : undefined }}
                    >
                        <Typography level="body-sm" noWrap>{p.label}</Typography>
                        <Typography level="body-xs" noWrap sx={{ color: 'text.tertiary' }}>{p.hint}</Typography>
                    </Box>
                ))}
            </Box>
        </Box>
    );
}

export interface MarkerDialogTarget {
    // The marker being edited, or null for a new one.
    marker: GanttMarker | null;
    // The form a new marker starts from (its day, range or not, its tags).
    initial?: MarkerForm;
}

export default function GanttMarkerDialog({
    target, markers, files, onClose, onSaved, onDraft, lastPlace, onPlace, noMarkerQuery,
}: {
    target: MarkerDialogTarget | null;
    // The markers on the chart, to put a new one beside and to offer tags from.
    markers: GanttMarker[];
    // Files a new marker can go at the end of.
    files: string[];
    onClose: () => void;
    // Written: what happened, and the marker as written (name '' when it was
    // deleted), so the chart can make sure it shows.
    onSaved: (msg: string, name: string, tags: string[], first: string) => void;
    // Where the last new marker went, and a place to remember this one's.
    lastPlace?: Place | null;
    onPlace?: (p: Place) => void;
    // The view draws no markers at all yet.
    noMarkerQuery?: boolean;
    // The form as it is being filled in (null when closed), so the chart can
    // draw where the marker will land.
    onDraft?: (f: MarkerForm | null) => void;
}) {
    const editing = target && target.marker;
    const [form, setForm] = React.useState<MarkerForm | null>(null);
    const [where, setWhere] = React.useState<Place | null>(null);
    const [tagText, setTagText] = React.useState('');
    const [error, setError] = React.useState('');
    const [busy, setBusy] = React.useState(false);
    const [confirmDelete, setConfirmDelete] = React.useState(false);

    // Placement for a new marker: beside an existing one (under the same
    // heading, or in the same file when it is at the top level) or at the end
    // of a file.
    const places = React.useMemo((): Place[] => {
        const out: Place[] = [];
        if (lastPlace) out.push(lastPlace);
        for (const m of markers) {
            if (m.parent) out.push({ value: `p:${m.parent}`, name: m.name, hint: m.filename || '', label: `Beside ${m.name}` });
            else if (m.filename) out.push({ ...filePlace(m.filename), label: `Beside ${m.name}`, name: m.name });
        }
        for (const f of files) out.push(filePlace(f));
        return uniquePlaces(out);
    }, [markers, files, lastPlace]);

    React.useEffect(() => {
        if (!target) return;
        const f = target.marker ? markerFormFrom(target.marker) : (target.initial as MarkerForm);
        setForm(f);
        setTagText(f.tags.join(' '));
        // Where the last one went, or beside a marker already on the chart -
        // never a file picked for you: a guess there writes the marker
        // somewhere it is hard to find again.
        const beside = markers.find(m => m.parent || m.filename);
        setWhere(lastPlace || (beside ? places.find(p => p.label === `Beside ${beside.name}`) || null : null));
        setError('');
        setBusy(false);
        setConfirmDelete(false);
        // Only when a dialog opens - re-reading the places while it is open
        // would throw away what has been chosen.
    }, [target]);

    // Tell the chart what is being written, and that nothing is once closed.
    React.useEffect(() => {
        if (onDraft) onDraft(target && form ? form : null);
    }, [target, form, onDraft]);
    React.useEffect(() => () => { if (onDraft) onDraft(null); }, [onDraft]);

    const tagsUsed = React.useMemo(() => {
        const s = new Set<string>();
        for (const m of markers) (m.tags || []).forEach(t => s.add(t));
        return Array.from(s).sort();
    }, [markers]);

    if (!target || !form) return null;
    const set = (patch: Partial<MarkerForm>) => setForm({ ...form, ...patch });
    const tags = tagText.split(/[\s,:]+/).filter(Boolean);
    const problem = markerFormError({ ...form, tags });

    const save = async () => {
        if (problem) { setError(problem); return; }
        const w = where ? where.value : '';
        const placed = w.startsWith('p:') ? { parentHash: w.slice(2) }
            : w.startsWith('f:') ? { filename: w.slice(2) } : {};
        if (!editing && !placed.parentHash && !placed.filename) {
            setError('Choose where the new marker goes.');
            return;
        }
        setBusy(true);
        setError('');
        try {
            const req = markerRequest({ ...form, tags }, editing ? { hash: target.marker!.hash } : placed);
            const res = await ODb.ganttMarker(req);
            if (!res || res.Ok === false) {
                setError((res && res.Msg) || 'the marker could not be saved');
                setBusy(false);
                return;
            }
            if (!editing && where && onPlace) onPlace(where);
            onSaved(editing ? `Marker ${form.name.trim()} updated` : `Marker ${form.name.trim()} added`,
                form.name.trim(), tags, form.startDate);
        } catch (e: any) {
            setError(e.message || 'the marker could not be saved');
            setBusy(false);
        }
    };

    const remove = async () => {
        if (!editing) return;
        if (!confirmDelete) { setConfirmDelete(true); return; }
        setBusy(true);
        try {
            const res = await ODb.ganttMarker({ Hash: target.marker!.hash, Delete: true });
            if (!res || res.Ok === false) {
                setError((res && res.Msg) || 'the marker could not be deleted');
                setBusy(false);
                return;
            }
            onSaved(`Marker ${target.marker!.name} deleted`, '', [], '');
        } catch (e: any) {
            setError(e.message || 'the marker could not be deleted');
            setBusy(false);
        }
    };

    const timeInput = (value: string, onChange: (v: string) => void, label: string) => (
        <Input size="sm" type="time" value={value} onChange={e => onChange(e.target.value)}
            slotProps={{ input: { 'aria-label': label } }} sx={{ width: 120 }} />
    );

    return (
        // No blur and no dimming, and the dialog to one side rather than over
        // the middle: the point of a marker is where it sits on the chart, so
        // the chart - with the marker drawn on it as the form is filled in -
        // stays in view behind it.
        // A click on the chart behind does not close it: with nothing dimmed,
        // the chart looks clickable, and a stray click would lose the form.
        <Modal open onClose={(_e, reason) => { if (reason !== 'backdropClick') onClose(); }}
            slotProps={{ backdrop: { sx: { backdropFilter: 'none', backgroundColor: 'transparent' } } }}>
            <ModalDialog
                sx={{
                    width: 460, maxWidth: '96vw',
                    top: 72, right: 24, left: 'auto', transform: 'none',
                    maxHeight: 'calc(100dvh - 96px)', overflowY: 'auto',
                    boxShadow: 'xl',
                }}
            >
                <Typography level="title-md">{editing ? 'Edit marker' : 'Add a marker'}</Typography>
                <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>
                    A marker is a heading whose date the chart draws as a line down it, or a band
                    for a range of days. It shows when the view's marker query finds it.
                </Typography>
                {noMarkerQuery && !editing && (
                    <Typography level="body-xs" sx={{ color: 'primary.600' }}>
                        {`This view shows no markers yet. Adding this one turns markers on, showing headings tagged :${tags[0] || 'milestone'}:.`}
                    </Typography>
                )}
                <Divider sx={{ my: 1 }} />
                <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
                    <FormControl size="sm">
                        <FormLabel>Name</FormLabel>
                        <Input size="sm" autoFocus value={form.name} onChange={e => set({ name: e.target.value })}
                            onKeyDown={e => { if (e.key === 'Enter') save(); }} />
                    </FormControl>
                    <RadioGroup orientation="horizontal" value={form.range ? 'range' : 'line'}
                        onChange={e => {
                            const range = e.target.value === 'range';
                            const d = parseGanttDate(form.startDate) || new Date();
                            set({
                                range,
                                endDate: range && !form.endDate
                                    ? dayKey(new Date(d.getFullYear(), d.getMonth(), d.getDate() + 2))
                                    : form.endDate,
                            });
                        }}
                        sx={{ gap: 2 }}>
                        <Radio size="sm" value="line" label="A line - one day" />
                        <Radio size="sm" value="range" label="A band - a range of days" />
                    </RadioGroup>
                    <Checkbox size="sm" label="At a time of day" checked={form.timed}
                        onChange={e => set({ timed: e.target.checked })} />
                    <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 1, flexWrap: 'wrap' }}>
                        <FormControl size="sm">
                            <FormLabel>{form.range ? 'From' : 'On'}</FormLabel>
                            <Input size="sm" type="date" value={form.startDate}
                                onChange={e => set({ startDate: e.target.value })} sx={{ width: 150 }}
                                slotProps={{ input: { 'aria-label': form.range ? 'First day' : 'Day' } }} />
                        </FormControl>
                        {form.timed && (
                            <>
                                {timeInput(form.startTime, v => set({ startTime: v }), 'Start time')}
                                <Typography level="body-xs" sx={{ color: 'text.tertiary', pb: 0.75 }}>until</Typography>
                                {timeInput(form.startUntil, v => set({ startUntil: v }), 'Until')}
                            </>
                        )}
                    </Box>
                    {form.range && (
                        <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 1, flexWrap: 'wrap' }}>
                            <FormControl size="sm">
                                <FormLabel>To (the last day)</FormLabel>
                                <Input size="sm" type="date" value={form.endDate}
                                    onChange={e => set({ endDate: e.target.value })} sx={{ width: 150 }}
                                    slotProps={{ input: { 'aria-label': 'Last day' } }} />
                            </FormControl>
                            {form.timed && (
                                <>
                                    {timeInput(form.endTime, v => set({ endTime: v }), 'Last day time')}
                                    <Typography level="body-xs" sx={{ color: 'text.tertiary', pb: 0.75 }}>until</Typography>
                                    {timeInput(form.endUntil, v => set({ endUntil: v }), 'Last day until')}
                                </>
                            )}
                        </Box>
                    )}
                    {form.range && form.timed && (
                        <Typography level="body-xs" sx={{ color: 'text.tertiary', mt: -0.75 }}>
                            Times on both days with an "until" make a span each day - a meeting at the same
                            hour every day of the range.
                        </Typography>
                    )}
                    {!form.range && (
                        <RadioGroup orientation="horizontal" value={form.kind}
                            onChange={e => set({ kind: e.target.value as 'date' | 'deadline' })} sx={{ gap: 2 }}>
                            <Radio size="sm" value="date" label="Its own date" />
                            <Radio size="sm" value="deadline" label="Its deadline" />
                        </RadioGroup>
                    )}
                    <FormControl size="sm">
                        <FormLabel>Tags</FormLabel>
                        <Input size="sm" value={tagText} onChange={e => setTagText(e.target.value)}
                            placeholder="milestone" sx={{ fontFamily: 'monospace' }} />
                        {tagsUsed.length > 0 && (
                            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 0.75 }}>
                                {tagsUsed.filter(t => tags.indexOf(t) < 0).map(t => (
                                    <Chip key={t} size="sm" variant="outlined"
                                        onClick={() => setTagText([...tags, t].join(' '))}>
                                        {`+ ${t}`}
                                    </Chip>
                                ))}
                            </Box>
                        )}
                    </FormControl>
                    {!editing && (
                        <FormControl size="sm">
                            <FormLabel>Where it goes</FormLabel>
                            <PlacePicker value={where} onChange={setWhere} places={places} />
                        </FormControl>
                    )}
                    <Box sx={{ bgcolor: 'background.level1', borderRadius: 'sm', px: 1, py: 0.75 }}>
                        <Typography level="body-xs" sx={{ color: 'text.tertiary' }}>Written as</Typography>
                        <Typography level="body-sm" sx={{ fontFamily: 'monospace' }} data-testid="marker-preview">
                            {previewOf(form)}
                        </Typography>
                    </Box>
                    {(error || (problem && form.name)) && (
                        <Typography level="body-xs" sx={{ color: 'danger.500' }}>{error || problem}</Typography>
                    )}
                    <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                        {editing && (
                            <Button size="sm" variant={confirmDelete ? 'solid' : 'plain'} color="danger"
                                disabled={busy} onClick={remove}>
                                {confirmDelete ? `Really delete ${target.marker!.name}?` : 'Delete'}
                            </Button>
                        )}
                        <Box sx={{ flex: 1 }} />
                        <Button size="sm" variant="plain" onClick={onClose}>Cancel</Button>
                        <Button size="sm" loading={busy} disabled={!!problem} onClick={save}>
                            {editing ? 'Save' : 'Add'}
                        </Button>
                    </Box>
                </Box>
            </ModalDialog>
        </Modal>
    );
}
