// The default look.
//
// `warp: 0` is the one that matters: the galaxy always forms itself while its
// alpha is hot and then the physics *freezes*, which is what lets a four
// thousand star database idle at full framerate. Turning warp up on a big one is
// meant to be expensive - it is O(n²) and says so on the slider.

import { StarmapSettings } from './types';

export const DEF: StarmapSettings = {
    repel: 2600,
    spring: 0.020,
    // An outline edge pulls less hard than a link. It has to pull at all - it is
    // what gathers a file's headings into a constellation rather than a cloud -
    // but at full strength the tree's own geometry would flatten the picture into
    // a dendrogram, and the point of a starmap is that it is not one.
    outline: 0.55,
    len: 80,
    center: 0.00030,
    heat: 0,
    warp: 0,
    shape: 'disc',
    nodeSize: 0.4,
    glow: 2,
    nebula: 0.35,
    linkAlpha: 0.85,
    // Fainter than a link, and deliberately: there are ten times as many of them
    // (every heading has exactly one) and at a link's brightness the galaxy is a
    // ball of wool.
    outlineAlpha: 0.30,
    linkW: 0.8,
    hue: 0,
    twinkle: 2.5,
    dust: 0.85,
    stars: 2.5,
    nameSize: 0.85,
    names: 2,
    novas: 2,
    hole: 2,
    spin: 1,
    comets: 250,
    meteors: 10,
    thrust: 1,
    vol: 1,
};

// A fresh copy, because the engine mutates its settings in place - a slider
// writes straight into the live object so a drag costs no React render.
export function defaultSettings(): StarmapSettings {
    return { ...DEF };
}
