// What a source block is, on this side of the wire.
//
// The server reads each `#+BEGIN_SRC` block rather than merely finding it: its
// language, the name another block calls it by, its switches, its babel header
// arguments, and its variables. A variable is the interesting part, because
// `:var data=monthly` looks exactly like `:var scale=2` and means something
// completely different - one names a table in the same file, the other is the
// number two. The server resolves that; this side draws the difference.

export type CodeArg = {
    Key: string;
    Value: string;
};

export type CodeVar = {
    Name: string;
    Value: string;
    // The name it refers to, or "" for a literal.
    Ref: string;
    // What that name is: "table" | "src" | "list" | "example" | "results".
    // Empty *with* a Ref means the name resolves to nothing - a block that
    // cannot run, and the thing most worth seeing.
    RefKind: string;
    RefFile: string;
    RefLine: number;
    Rows: number;
    Cols: number;
    Index: string;
};

export type CodeBlock = {
    Filename: string;
    Id: number;
    Name: string;
    Lang: string;
    Heading: string;
    Olp: string[] | null;
    Hash: string;
    Line: number;
    EndLine: number;
    Code: string;
    Lines: number;
    Switches: string[] | null;
    Args: CodeArg[] | null;
    Vars: CodeVar[] | null;
    Result: string;
    ResultKind: string;
};

export type CodeLang = { Lang: string; Count: number };

export type CodeResult = {
    Ok: boolean;
    Msg: string;
    // "table" | "list" | "file" | "text"
    Kind: string;
    // The result as org text of that shape, so a table can go straight to the
    // table view the Tables tab uses rather than through a second format.
    Result: string;
    // What the program actually printed, for when the shape was guessed wrong.
    Raw: string;
    Stderr: string;
    Code: number;
    Seconds: number;

    // When the result names a file, what the server found at that path. The
    // link is resolved server side because only that side knows what the name
    // is relative to - a block runs beside the org file it is written in.
    File: string;
    // Where this server serves it from, or "" when it is outside the org
    // directories and so not served at all.
    Url: string;
    Exists: boolean;
    Bytes: number;
    // The contents, when it is text and small enough to be worth showing.
    Text: string;
    Truncated: boolean;
    // "image" | "audio" | "video" | "pdf" | "text" | "binary"
    Media: string;
    // The language to colour Text as, from the extension.
    TextLang: string;
};

export type CodeIndex = {
    Blocks: CodeBlock[];
    Langs: CodeLang[];
    Total: number;
};

// What to call a block on screen. Its name if it has one, because that is what
// anything else in the file calls it by; otherwise the heading it sits under,
// which is how a person would point at it.
export function blockTitle(b: CodeBlock): string {
    if (b.Name) return b.Name;
    const olp = b.Olp || [];
    if (olp.length > 0) return olp[olp.length - 1];
    return `${b.Lang || 'block'} block`;
}

// Whether a variable points at something in the org file rather than being a
// value written out in full.
export function isReference(v: CodeVar): boolean {
    return v.Ref !== '';
}

// A reference that names something nothing answers to. Worth saying out loud
// in its own colour: the block cannot run.
export function isBrokenReference(v: CodeVar): boolean {
    return v.Ref !== '' && v.RefKind === '';
}

// How many of a block's variables come out of the file rather than out of the
// header line, which is what the list uses to mark the blocks that are a step
// in a chain rather than a thing on their own.
export function referenceCount(b: CodeBlock): number {
    return (b.Vars || []).filter(isReference).length;
}

// What a reference is, said the way somebody would say it: "table monthly,
// 4 rows × 3 columns".
export function referenceText(v: CodeVar): string {
    if (v.RefKind === '') return `${v.Ref} — nothing of that name`;
    if (v.RefKind === 'table' && v.Rows > 0) {
        const rows = v.Rows === 1 ? '1 row' : `${v.Rows} rows`;
        const cols = v.Cols === 1 ? '1 column' : `${v.Cols} columns`;
        return `table ${v.Ref} · ${rows} × ${cols}`;
    }
    const kind = v.RefKind === 'src' ? 'block' : v.RefKind;
    return `${kind} ${v.Ref}`;
}

// The block as it is written in the file, for showing it through the org
// highlighter. Rebuilt rather than kept as raw text because the server hands
// over the parts - and rebuilding is what proves the parts are all there.
//
// The body is indented by two, which is what the server writes back when a
// block is saved: the code arrives dedented, because that is what an editor
// wants and what an interpreter needs.
export function blockSource(b: CodeBlock, code?: string): string {
    const lines: string[] = [];
    if (b.Name) lines.push(`#+NAME: ${b.Name}`);
    lines.push(headerLine(b));
    for (const l of ((code === undefined ? b.Code : code) || '').split('\n')) {
        lines.push(l === '' ? '' : '  ' + l);
    }
    lines.push('#+END_SRC');
    return lines.join('\n');
}

// The #+BEGIN_SRC line, in org's own order: language, switches, variables,
// then the rest of the header arguments. Said the same way here and in
// headerLine in code.go, so a block saved from worg reads like one written by
// hand - change one and change both.
export function headerLine(b: {
    Lang: string; Switches: string[] | null; Vars: CodeVar[] | null; Args: CodeArg[] | null;
}): string {
    const parts = ['#+BEGIN_SRC'];
    if (b.Lang) parts.push(b.Lang);
    for (const sw of b.Switches || []) if (sw.trim()) parts.push(sw.trim());
    for (const v of b.Vars || []) {
        if (v.Name.trim()) parts.push(`:var ${v.Name.trim()}=${v.Value.trim()}`);
    }
    for (const a of b.Args || []) {
        const k = a.Key.trim();
        if (!k || k.toLowerCase() === 'var') continue;
        parts.push(a.Value.trim() ? `:${k} ${a.Value.trim()}` : `:${k}`);
    }
    return parts.join(' ');
}

// The file a block is in, said the way the Tables tab says one: the name you
// read, with the path kept for the tooltip.
export function baseName(path: string): string {
    const parts = (path || '').split(/[\\/]/);
    return parts[parts.length - 1] || path;
}

// A colour per language, stable, so the one you work in is recognisable down
// a list before the badge has been read. The same trick the contact avatars
// and the capture templates use.
const HUES = [210, 28, 160, 265, 340, 190, 45, 310, 130, 88];
export function langHue(lang: string): number {
    let h = 0;
    const s = lang || 'none';
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return HUES[h % HUES.length];
}
